  ('la-pt', 'la-t254', 'frase', 'A1', array['trecho']::text[], null, '28e14cc3', array['e como oleiro de vaso os quebrarás', 'e como vaso de oleiro os quebrará', 'e como vaso de oleiro os quebrarás', 'e como vaso de oleiro os quebraste', 'e como vaso de oleiro te quebrarão']::text[]),
  ('la-pt', 'la-t255', 'frase', 'A1', array['trecho']::text[], null, '8bd7a03c', array['E agora, os reis compreendem; deixai-vos instruir, vós que julgais a terra', 'E agora, reis, compreendei; deixai-vos instruir, vós que julgais a terra', 'E agora, reis, compreendei; deixai-vos instruir, vós que julgastes a terra', 'E agora, reis, compreendei; instruí, vós que julgais a terra', 'E agora, reis, compreendereis; deixai-vos instruir, vós que julgais a terra']::text[]),
  ('la-pt', 'la-t256', 'frase', 'A1', array['trecho']::text[], null, '74e716ac', array['O Senhor vos serve com temor e exulta com tremor', 'Serve ao Senhor com temor e exulta nele com tremor', 'Servi ao Senhor com temor e exultai nele com tremor', 'Servi com o Senhor no temor e exultai com ele no tremor', 'Servireis ao Senhor com temor e exultareis nele com tremor']::text[]),
