  ('la-pt', 'la-u585', 'frase', 'A1', array['frase de uso']::text[], 'la-p655', 'f0b729c8', array['Que não houve nenhuma súplica.', 'Que não tenha havido nenhuma guerra.', 'Que não tenha havido nenhuma lei.', 'Que não tenha havido nenhuma súplica.', 'Que tenha havido alguma súplica.']::text[]),
  ('la-pt', 'la-u586', 'frase', 'A1', array['frase de uso']::text[], 'la-p656', 'f57458dd', array['Já me alcançarás, minha mãe.', 'Já te alcancei, minha mãe.', 'Já te alcançarei, minha mãe.', 'Já te deixarei, minha mãe.', 'Já te esperarei, minha mãe.']::text[]),
  ('la-pt', 'la-u587', 'frase', 'A1', array['frase de uso']::text[], 'la-p657', '55e3f678', array['E cresceu ele, e nossos pais.', 'E morreram eles, e nosso pai.', 'E morrerá ele, e nossos pais.', 'E morreu ele, e nossos pais.', 'E nasceu ele, e nossos pais.']::text[]),
  ('la-pt', 'la-u588', 'frase', 'A1', array['frase de uso']::text[], 'la-p658', 'e90a7032', array['Senhor, a tua glória é para sempre.', 'Senhor, a tua misericórdia será para sempre.', 'Senhor, a tua misericórdia é para sempre.', 'Senhor, a tua paz é para sempre.', 'Senhor, as tuas misericórdias são para sempre.']::text[])
